css:
.qb-quote { font-family: Impact, 'Arial Black', sans-serif; background: linear-gradient(135deg, #0f0c29, #302b63, #24243e); color: #fff; padding: 48px 32px; margin: 12px 0; border-radius: 8px; text-align: center; }
.qb-quote-text { font-size: 1.8em; line-height: 1.4; text-transform: uppercase; letter-spacing: 0.02em; white-space: pre-wrap; text-shadow: 2px 2px 4px rgba(0,0,0,0.5); }
.qb-author { font-size: 1.2em; color: #ffd54f; margin-top: 16px; letter-spacing: 0.1em; }
.qb-divider { border: none; border-top: 2px solid #ffd54f; width: 60px; margin: 16px auto; }
.qb-site-header { display: flex; justify-content: center; gap: 12px; font-size: 0.8em; color: #aaa; margin-top: 12px; }
.qb-rating { margin-top: 8px; color: #ffd54f; font-weight: bold; }
.qb-meta { margin-top: 6px; font-size: 0.8em; color: #999; }
.qb-source-url { margin-top: 8px; font-size: 0.8em; }
.qb-source-url a { color: #9ecbff; }
.qb-branding { margin-top: 12px; font-size: 0.75em; color: #777; text-align: center; }
